-- Synthetic local fixtures only. SMTP is never contacted; all changes roll back.
BEGIN;
CREATE FUNCTION pg_temp.check_email(ok boolean,label text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'Email assertion failed: %',label; END IF; END $$;
SELECT set_config('email.actor',(SELECT id::text FROM auth.users LIMIT 1),true);
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('email.actor'),'role','service_role')::text,true);
INSERT INTO public.organizations(id,name,slug) VALUES('51000000-0000-4000-8000-000000000001','Email fixture','email-fixture'),('51000000-0000-4000-8000-000000000002','Foreign email fixture','email-foreign-fixture');
INSERT INTO public.organization_members(organization_id,user_id,role,status) SELECT id,current_setting('email.actor')::uuid,'owner','active' FROM public.organizations WHERE slug IN('email-fixture','email-foreign-fixture');
INSERT INTO public.organization_smtp_configs(id,organization_id,provider,host,port,user_email,password_encrypted,iv,from_email,from_name,is_verified) VALUES('52000000-0000-4000-8000-000000000001','51000000-0000-4000-8000-000000000001','custom','smtp.example.com',587,'sender@example.com','synthetic','synthetic','sender@example.com','Fixture sender',true);
SELECT set_config('email.import',(public.prepare_marketing_email_import('51000000-0000-4000-8000-000000000001',current_setting('email.actor')::uuid,'[{"row":2,"name":"Synthetic","email":"recipient@example.com"}]')->>'token'),true);
SELECT set_config('email.list',(public.confirm_marketing_email_import('51000000-0000-4000-8000-000000000001',current_setting('email.actor')::uuid,current_setting('email.import')::uuid,ARRAY[2],'Email list')->>'listId'),true);
SELECT pg_temp.check_email(NOT public.marketing_email_allowed('51000000-0000-4000-8000-000000000001','recipient@example.com'),'import does not imply consent');
SELECT pg_temp.check_email((SELECT count(*)=1 FROM public.leads WHERE organization_id='51000000-0000-4000-8000-000000000001' AND email='recipient@example.com' AND contact_type='prospect' AND status='marketing_contact'),'email-only contact stays outside pipeline');
SELECT set_config('email.permission',public.prepare_marketing_email_list_authorization('51000000-0000-4000-8000-000000000001',current_setting('email.actor')::uuid,current_setting('email.list')::uuid)->>'token',true);
SELECT public.confirm_marketing_email_list_authorization('51000000-0000-4000-8000-000000000001',current_setting('email.actor')::uuid,current_setting('email.permission')::uuid,true,'Synthetic authorization');
SELECT pg_temp.check_email(public.marketing_email_allowed('51000000-0000-4000-8000-000000000001','recipient@example.com'),'list grants email permission');
SELECT pg_temp.check_email(NOT public.marketing_email_allowed('51000000-0000-4000-8000-000000000002','recipient@example.com'),'email permission isolated by tenant');
INSERT INTO public.marketing_audiences(id,organization_id,name,filter_config) VALUES('53000000-0000-4000-8000-000000000001','51000000-0000-4000-8000-000000000001','Fixture selection',jsonb_build_object('list_id',current_setting('email.list'),'has_email',true));
INSERT INTO public.marketing_campaigns(id,organization_id,name,channel,smtp_config_id,audience_id,delivery_config) VALUES('54000000-0000-4000-8000-000000000001','51000000-0000-4000-8000-000000000001','Fixture email','email','52000000-0000-4000-8000-000000000001','53000000-0000-4000-8000-000000000001','{"mode":"growth","humanize":false,"timezone":"America/Bogota","recipient_cooldown_hours":24}');
INSERT INTO public.marketing_sequences(id,organization_id,campaign_id,name,trigger_type,is_active) VALUES('55000000-0000-4000-8000-000000000001','51000000-0000-4000-8000-000000000001','54000000-0000-4000-8000-000000000001','Main','manual',true);
INSERT INTO public.marketing_steps(id,organization_id,sequence_id,name,type,order_index,content) VALUES('56000000-0000-4000-8000-000000000001','51000000-0000-4000-8000-000000000001','55000000-0000-4000-8000-000000000001','Email','email',0,'{"subject":"Hello {{empresa}}","body":"Synthetic"}');
SELECT pg_temp.check_email(public.read_marketing_email_preflight('51000000-0000-4000-8000-000000000001','54000000-0000-4000-8000-000000000001')->>'missingData'='1','missing personalization detected');
UPDATE public.marketing_steps SET content='{"subject":"Hello {{nombre}}","body":"Synthetic"}' WHERE id='56000000-0000-4000-8000-000000000001';
SELECT set_config('email.ticket',public.prepare_marketing_email_activation('51000000-0000-4000-8000-000000000001',current_setting('email.actor')::uuid,'54000000-0000-4000-8000-000000000001')->>'token',true);
SELECT public.confirm_marketing_email_activation('51000000-0000-4000-8000-000000000001',current_setting('email.actor')::uuid,'54000000-0000-4000-8000-000000000001',current_setting('email.ticket')::uuid);
SELECT public.confirm_marketing_email_activation('51000000-0000-4000-8000-000000000001',current_setting('email.actor')::uuid,'54000000-0000-4000-8000-000000000001',current_setting('email.ticket')::uuid);
SELECT pg_temp.check_email((SELECT count(*)=1 FROM public.marketing_enrollments WHERE campaign_id='54000000-0000-4000-8000-000000000001'),'activation is idempotent');
UPDATE public.marketing_enrollments SET next_run_at=now()-interval '1 second' WHERE campaign_id='54000000-0000-4000-8000-000000000001';
SELECT set_config('email.enrollment',(SELECT id::text FROM public.claim_marketing_email_enrollments(1) WHERE campaign_id='54000000-0000-4000-8000-000000000001'),true);
SELECT set_config('email.claim',(SELECT claim_token::text FROM public.marketing_enrollments WHERE id=current_setting('email.enrollment')::uuid),true);
SELECT set_config('email.operation',public.reserve_marketing_email('51000000-0000-4000-8000-000000000001',current_setting('email.enrollment')::uuid,'56000000-0000-4000-8000-000000000001',current_setting('email.claim')::uuid)::text,true);
SELECT pg_temp.check_email(current_setting('email.operation')::jsonb->>'state'='reserved','SMTP reservation succeeds');
SELECT pg_temp.check_email(public.reserve_marketing_email('51000000-0000-4000-8000-000000000001',current_setting('email.enrollment')::uuid,'56000000-0000-4000-8000-000000000001',current_setting('email.claim')::uuid)->>'state'='sending','inflight mail is never duplicated');
SELECT public.finish_marketing_email('51000000-0000-4000-8000-000000000001',(current_setting('email.operation')::jsonb->>'id')::uuid,'accepted','<synthetic@example.com>',NULL);
SELECT pg_temp.check_email(public.reserve_marketing_email('51000000-0000-4000-8000-000000000001',current_setting('email.enrollment')::uuid,'56000000-0000-4000-8000-000000000001',current_setting('email.claim')::uuid)->>'state'='accepted','accepted mail recovers without redispatch');
SELECT pg_temp.check_email(public.unsubscribe_marketing_email(encode(extensions.digest(current_setting('email.operation')::jsonb->>'unsubscribeToken','sha256'),'hex')),'token revokes permission');
SELECT pg_temp.check_email(NOT public.marketing_email_allowed('51000000-0000-4000-8000-000000000001','recipient@example.com'),'unsubscribe prevents further email');
SELECT pg_temp.check_email(NOT public.unsubscribe_marketing_email(repeat('0',64)),'invalid token cannot revoke permission');
SELECT set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('email.actor'),'role','authenticated')::text,true);
SELECT pg_temp.check_email(public.read_marketing_campaign_metrics('51000000-0000-4000-8000-000000000001','54000000-0000-4000-8000-000000000001')#>>'{delivery,accepted}'='1','shared metrics route dispatches to email');
SELECT pg_temp.check_email(public.read_marketing_campaign_page('51000000-0000-4000-8000-000000000001','', 'all','52000000-0000-4000-8000-000000000001')#>>'{rows,0,channelType}'='email','SMTP filter and email badge survive pagination');
SELECT pg_temp.check_email(jsonb_array_length(public.read_marketing_history('51000000-0000-4000-8000-000000000001','54000000-0000-4000-8000-000000000001')->'items')=1,'email history works in shared view');
SELECT pg_temp.check_email(jsonb_array_length(public.read_marketing_step_history('51000000-0000-4000-8000-000000000001','54000000-0000-4000-8000-000000000001')->'items')=1,'email step history works in shared view');
SELECT pg_temp.check_email(NOT has_table_privilege('authenticated','public.marketing_email_outbox','SELECT'),'public sessions cannot read email capabilities or credentials');
SELECT pg_temp.check_email(NOT has_function_privilege('authenticated','public.reserve_marketing_email(uuid,uuid,uuid,uuid)','EXECUTE'),'public sessions cannot reserve email sends');
ROLLBACK;
